function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  // Parse and validate thresholds
  const thresholds: Record<string, number> = {};
  const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];

  if (options.threshold) {
    const thresholdArray = Array.isArray(options.threshold) ? options.threshold : [options.threshold];
    for (const threshold of thresholdArray) {
      const match = threshold.match(/^([a-z_]+)=([0-9]*\.?[0-9]+)$/);
      if (!match) {
        log.error(`Malformed threshold: "${threshold}". Expected format: metric=<number>`);
        process.exit(2);
      }
      const [, metricId, minStr] = match;
      const min = parseFloat(minStr);
      if (isNaN(min) || min < 0 || min > 1) {
        log.error(`Invalid threshold value for ${metricId}: "${minStr}". Must be a number between 0 and 1.`);
        process.exit(2);
      }
      if (!validMetricIds.includes(metricId)) {
        log.error(`Unknown metric id: "${metricId}". Valid metric ids are: ${validMetricIds.join(', ')}`);
        process.exit(2);
      }
      thresholds[metricId] = min;
    }
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: Object.keys(thresholds).length > 0 ? thresholds : undefined
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  // Exit with appropriate code based on threshold results
  if (report.passed === false) {
    process.exit(1);
  }
}

