export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  // Evaluate thresholds if provided
  let passed = true;
  const thresholdResults = [];

  if (thresholds && typeof thresholds === 'object') {
    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score ?? null;
      const thresholdPassed = score !== null && score >= min;
      if (!thresholdPassed) {
        passed = false;
      }
      thresholdResults.push({
        metric: metricId,
        min,
        score,
        passed: thresholdPassed
      });
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
