    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('evaluates thresholds and passes when all metrics meet thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['hello', 'world'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.5,
      score: 1,
      passed: true
    });
  });

  it('evaluates thresholds and fails when a metric falls below threshold', () => {
    const evaluations = runEvaluations({
      outputs: ['hello', 'world'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds[0].passed).toBe(true);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: ['hello'],
      references: [] // Mismatch in lengths causes exact_match to have no score
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });
    expect(report.passed).toBe(false);
    const exactMatchThreshold = report.thresholds.find(t => t.metric === 'exact_match');
    expect(exactMatchThreshold.score).toBeNull();
    expect(exactMatchThreshold.passed).toBe(false);
  });

  it('evaluates multiple thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['hello world'],
      references: ['hello world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.8,
        toxicity: 0.8
      }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds.every(t => t.passed)).toBe(true);
  });

  it('does not add threshold fields without thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });
    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });

  it('includes thresholds in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });
    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });
    const content = fs.readFileSync(markdownPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('exact_match');
    expect(content).toContain('PASS');
  });
});

